module riscv_cpu (
    input  wire        clk,
    input  wire        rst_n,
    
    // Instruction Memory Interface
    output wire [31:0] imem_addr,
    input  wire [31:0] imem_data,
    
    // Data Memory Interface
    output wire [31:0] dmem_addr,
    output wire [31:0] dmem_wdata,
    output wire        dmem_wen,
    output wire [3:0]  dmem_be,      // Byte enable
    input  wire [31:0] dmem_rdata,
    
    // Debug Interface (optional)
    output wire [31:0] debug_pc,
    output wire [31:0] debug_inst
);

// =================================================================
// RISC-V RV32I Opcodes, Funct3, Funct7
// =================================================================

// Opcodes
`define OPCODE_R_TYPE   7'b0110011
`define OPCODE_I_TYPE   7'b0010011
`define OPCODE_LW       7'b0000011
`define OPCODE_S_TYPE   7'b0100011
`define OPCODE_B_TYPE   7'b1100011
`define OPCODE_JAL      7'b1101111
`define OPCODE_JALR     7'b1100111

// Funct3
`define FUNCT3_ADD_SUB  3'b000
`define FUNCT3_SLT      3'b010
`define FUNCT3_XOR      3'b100
`define FUNCT3_OR       3'b110
`define FUNCT3_AND      3'b111

`define FUNCT3_BEQ      3'b000
`define FUNCT3_BNE      3'b001
`define FUNCT3_BLT      3'b100
`define FUNCT3_BGE      3'b101

`define FUNCT3_LW       3'b010
`define FUNCT3_SW       3'b010

// Funct7
`define FUNCT7_ADD      7'b0000000
`define FUNCT7_SUB      7'b0100000

// ALU Operations (internal encoding)
`define ALU_ADD     4'b0000
`define ALU_SUB     4'b0001
`define ALU_AND     4'b0010
`define ALU_OR      4'b0011
`define ALU_XOR     4'b0100
`define ALU_SLT     4'b0101 // Set Less Than (signed)

// NOP instruction (ADDI x0, x0, 0)
`define NOP_INST 32'h00000013

// =================================================================
// Internal Wires and Registers
// =================================================================

// PC Register
reg [31:0] pc_reg;
wire [31:0] pc_next;

// Instruction Fetch (IF) Stage
wire [31:0] if_pc;
wire [31:0] if_inst;

// IF/ID Pipeline Register
reg [31:0] ifid_pc;
reg [31:0] ifid_inst;

// Instruction Decode (ID) Stage
wire [6:0] id_opcode;
wire [4:0] id_rs1_addr;
wire [4:0] id_rs2_addr;
wire [4:0] id_rd_addr;
wire [2:0] id_funct3;
wire [6:0] id_funct7;
wire [31:0] id_imm;
wire [31:0] id_rs1_data_rf; // Data read from RegFile for rs1
wire [31:0] id_rs2_data_rf; // Data read from RegFile for rs2

// Control Signals (ID stage output)
reg id_regwrite;
reg id_memread;
reg id_memwrite;
reg id_alu_src;    // 0: rs2, 1: immediate
reg id_branch;
reg id_jump;
reg [3:0] id_alu_op;

// ID/EX Pipeline Register
reg [31:0] idex_pc;
reg [31:0] idex_rs1_data;
reg [31:0] idex_rs2_data;
reg [4:0]  idex_rs1_addr;
reg [4:0]  idex_rs2_addr;
reg [4:0]  idex_rd_addr;
reg [31:0] idex_imm;
reg idex_regwrite;
reg idex_memread;
reg idex_memwrite;
reg idex_alu_src;
reg idex_branch;
reg idex_jump;
reg [3:0]  idex_alu_op;

// Execute (EX) Stage
wire [31:0] ex_op1;
wire [31:0] ex_op2;
wire [31:0] ex_alu_result;
wire ex_branch_taken;
wire [31:0] ex_branch_target;
wire [31:0] ex_jump_target;

// EX/MEM Pipeline Register
reg [31:0] exmem_pc; // For JAL/JALR link address
reg [31:0] exmem_alu_result;
reg [31:0] exmem_mem_wdata; // rs2_data for store
reg [4:0]  exmem_rd_addr;
reg exmem_regwrite;
reg exmem_memread;
reg exmem_memwrite;
reg exmem_branch_taken; // Propagate branch taken decision
reg exmem_jump;

// Memory Access (MEM) Stage
wire [31:0] mem_read_data;

// MEM/WB Pipeline Register
reg [31:0] memwb_alu_result;
reg [31:0] memwb_mem_data;
reg [4:0]  memwb_rd_addr;
reg memwb_regwrite;
reg memwb_memread; // CRITICAL: MUST be declared as reg

// Write Back (WB) Stage
wire [31:0] wb_wdata;
wire [4:0]  wb_waddr;
wire wb_wen;

// Hazard Control Signals
reg stall_ifid; // Stall IF and IF/ID pipeline register
reg flush_ifid; // Flush IF/ID pipeline register
reg flush_idex; // Flush ID/EX pipeline register

// Forwarding Unit Signals
reg [1:0] forward_a_sel; // 00: no fwd, 01: EX/MEM, 10: MEM/WB
reg [1:0] forward_b_sel; // 00: no fwd, 01: EX/MEM, 10: MEM/WB

// =================================================================
// Debug Outputs
// =================================================================
assign debug_pc = pc_reg;
assign debug_inst = if_inst;

// =================================================================
// Register File
// =================================================================
reg [31:0] reg_file [0:31];
    reg idex_opcode;
integer i;

always @(posedge clk) begin
    if (!rst_n) begin
        for (i = 0; i < 32; i = i + 1) begin
            reg_file[i] <= 32'b0;
        end
    end else if (wb_wen) begin
        if (wb_waddr != 5'b00000) begin // x0 is hardwired to 0
            reg_file[wb_waddr] <= wb_wdata;
        end
    end
end

assign id_rs1_data_rf = (id_rs1_addr == 5'b00000) ? 32'b0 : reg_file[id_rs1_addr];
assign id_rs2_data_rf = (id_rs2_addr == 5'b00000) ? 32'b0 : reg_file[id_rs2_addr];

// =================================================================
// PC Logic
// =================================================================
assign if_pc = pc_reg;
assign imem_addr = if_pc;
assign if_inst = imem_data;

assign pc_next = (exmem_branch_taken || exmem_jump) ? ex_branch_target : (pc_reg + 4);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        pc_reg <= 32'h00000000;
    end else if (~stall_ifid) begin // Only update PC if not stalled
        pc_reg <= pc_next;
    end
end

// =================================================================
// IF/ID Pipeline Register
// =================================================================
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ifid_pc   <= 32'b0;
        ifid_inst <= `NOP_INST;
    end else if (~stall_ifid) begin // Only update if not stalled
        if (flush_ifid) begin // If flushed, insert NOP
            ifid_pc   <= 32'b0;
            ifid_inst <= `NOP_INST;
        end else begin
            ifid_pc   <= if_pc;
            ifid_inst <= if_inst;
        end
    end
end

// =================================================================
// ID Stage: Instruction Decode & Control Unit
// =================================================================
assign id_opcode  = ifid_inst[6:0];
assign id_rs1_addr = ifid_inst[19:15];
assign id_rs2_addr = ifid_inst[24:20];
assign id_rd_addr  = ifid_inst[11:7];
assign id_funct3  = ifid_inst[14:12];
assign id_funct7  = ifid_inst[31:25];

// Immediate Generation
wire [31:0] imm_i_type = {{20{ifid_inst[31]}}, ifid_inst[31:20]};
wire [31:0] imm_s_type = {{20{ifid_inst[31]}}, ifid_inst[31:25], ifid_inst[11:7]};
wire [31:0] imm_b_type = {{20{ifid_inst[31]}}, ifid_inst[7], ifid_inst[30:25], ifid_inst[11:8], 1'b0};
wire [31:0] imm_j_type = {{12{ifid_inst[31]}}, ifid_inst[19:12], ifid_inst[20], ifid_inst[30:21], 1'b0};
wire [31:0] imm_jalr_type = imm_i_type; // JALR uses I-type immediate

always @(*) begin
    id_regwrite = 1'b0;
    id_memread  = 1'b0;
    id_memwrite = 1'b0;
    id_alu_src  = 1'b0; // Default: rs2
    id_branch   = 1'b0;
    id_jump     = 1'b0;
    id_alu_op   = `ALU_ADD; // Default ALU op

    case (id_opcode)
        `OPCODE_R_TYPE: begin // R-type instructions
            id_regwrite = 1'b1;
            id_alu_src  = 1'b0; // rs2
            case (id_funct3)
                `FUNCT3_ADD_SUB: begin
                    if (id_funct7 == `FUNCT7_ADD) id_alu_op = `ALU_ADD;
                    else if (id_funct7 == `FUNCT7_SUB) id_alu_op = `ALU_SUB;
                end
                `FUNCT3_SLT: id_alu_op = `ALU_SLT;
                `FUNCT3_XOR: id_alu_op = `ALU_XOR;
                `FUNCT3_OR:  id_alu_op = `ALU_OR;
                `FUNCT3_AND: id_alu_op = `ALU_AND;
                default: begin end // NOP or unsupported
            endcase
        end
        `OPCODE_I_TYPE: begin // I-type (ALU immediate)
            id_regwrite = 1'b1;
            id_alu_src  = 1'b1; // immediate
            case (id_funct3)
                `FUNCT3_ADD_SUB: id_alu_op = `ALU_ADD; // ADDI
                `FUNCT3_SLT: id_alu_op = `ALU_SLT; // SLTI
                `FUNCT3_XOR: id_alu_op = `ALU_XOR; // XORI
                `FUNCT3_OR:  id_alu_op = `ALU_OR;  // ORI
                `FUNCT3_AND: id_alu_op = `ALU_AND; // ANDI
                default: begin end // NOP or unsupported
            endcase
        end
        `OPCODE_LW: begin // Load Word
            id_regwrite = 1'b1;
            id_memread  = 1'b1;
            id_alu_src  = 1'b1; // immediate for address calculation
            id_alu_op   = `ALU_ADD;
        end
        `OPCODE_S_TYPE: begin // Store Word
            id_memwrite = 1'b1;
            id_alu_src  = 1'b1; // immediate for address calculation
            id_alu_op   = `ALU_ADD;
        end
        `OPCODE_B_TYPE: begin // Branch
            id_branch   = 1'b1;
            id_alu_op   = `ALU_SUB; // For comparison
        end
        `OPCODE_JAL: begin // JAL
            id_regwrite = 1'b1;
            id_jump     = 1'b1;
            id_alu_op   = `ALU_ADD; // No ALU op needed for JAL, but set default
        end
        `OPCODE_JALR: begin // JALR
            id_regwrite = 1'b1;
            id_jump     = 1'b1;
            id_alu_op   = `ALU_ADD; // No ALU op needed for JALR, but set default
        end
        default: begin end // NOP or unsupported
    endcase
end

// Immediate selection
always @(*) begin
    case (id_opcode)
        `OPCODE_I_TYPE, `OPCODE_LW, `OPCODE_JALR: id_imm = imm_i_type;
        `OPCODE_S_TYPE: id_imm = imm_s_type;
        `OPCODE_B_TYPE: id_imm = imm_b_type;
        `OPCODE_JAL:    id_imm = imm_j_type;
        default:        id_imm = 32'b0;
    endcase
end

// =================================================================
// Hazard Detection Unit (ID Stage)
// =================================================================
// Load-Use Hazard Detection
always @(*) begin
    stall_ifid = 1'b0;
    if (idex_memread && (idex_rd_addr != 5'b00000)) begin
        if ((idex_rd_addr == id_rs1_addr) || (idex_rd_addr == id_rs2_addr)) begin
            stall_ifid = 1'b1;
        end
    end
end

// Control Hazard Detection (Branch/Jump taken)
// Branch/Jump taken decision is made in EX stage.
// exmem_branch_taken or exmem_jump will be asserted if a branch/jump in EX stage was taken.
// This means the instruction fetched in IF and decoded in ID is incorrect.
assign flush_ifid = (exmem_branch_taken || exmem_jump);
assign flush_idex = (exmem_branch_taken || exmem_jump); // Also flush ID/EX register

// =================================================================
// ID/EX Pipeline Register
// =================================================================
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        idex_pc         <= 32'b0;
        idex_rs1_data   <= 32'b0;
        idex_rs2_data   <= 32'b0;
        idex_rs1_addr   <= 5'b0;
        idex_rs2_addr   <= 5'b0;
        idex_rd_addr    <= 5'b0;
        idex_imm        <= 32'b0;
        idex_regwrite   <= 1'b0;
        idex_memread    <= 1'b0;
        idex_memwrite   <= 1'b0;
        idex_alu_src    <= 1'b0;
        idex_branch     <= 1'b0;
        idex_jump       <= 1'b0;
        idex_alu_op     <= `ALU_ADD;
    end else if (~stall_ifid) begin // Only update if not stalled
        if (flush_idex) begin // If flushed, insert NOP (clear control signals)
            idex_pc         <= 32'b0;
            idex_rs1_data   <= 32'b0;
            idex_rs2_data   <= 32'b0;
            idex_rs1_addr   <= 5'b0;
            idex_rs2_addr   <= 5'b0;
            idex_rd_addr    <= 5'b0;
            idex_imm        <= 32'b0;
            idex_regwrite   <= 1'b0;
            idex_memread    <= 1'b0;
            idex_memwrite   <= 1'b0;
            idex_alu_src    <= 1'b0;
            idex_branch     <= 1'b0;
            idex_jump       <= 1'b0;
            idex_alu_op     <= `ALU_ADD;
        end else begin
            idex_pc         <= ifid_pc;
            idex_rs1_data   <= id_rs1_data_rf;
            idex_rs2_data   <= id_rs2_data_rf;
            idex_rs1_addr   <= id_rs1_addr;
            idex_rs2_addr   <= id_rs2_addr;
            idex_rd_addr    <= id_rd_addr;
            idex_imm        <= id_imm;
            idex_regwrite   <= id_regwrite;
            idex_memread    <= id_memread;
            idex_memwrite   <= id_memwrite;
            idex_alu_src    <= id_alu_src;
            idex_branch     <= id_branch;
            idex_jump       <= id_jump;
            idex_alu_op     <= id_alu_op;
        end
    end
end

// =================================================================
// EX Stage: Execute
// =================================================================

// Forwarding Unit
always @(*) begin
    forward_a_sel = 2'b00; // Default: no forwarding
    forward_b_sel = 2'b00;

    // EX/MEM hazard for rs1
    if (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs1_addr)) begin
        forward_a_sel = 2'b01; // Forward from EX/MEM
    end
    // MEM/WB hazard for rs1
    if (memwb_regwrite && (memwb_rd_addr != 5'b00000) && (memwb_rd_addr == idex_rs1_addr)) begin
        // If EX/MEM also has a hazard for the same register, EX/MEM takes precedence (newer data)
        if (! (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs1_addr)) ) begin
            forward_a_sel = 2'b10; // Forward from MEM/WB
        end
    end

    // EX/MEM hazard for rs2
    if (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs2_addr)) begin
        forward_b_sel = 2'b01; // Forward from EX/MEM
    end
    // MEM/WB hazard for rs2
    if (memwb_regwrite && (memwb_rd_addr != 5'b00000) && (memwb_rd_addr == idex_rs2_addr)) begin
        // If EX/MEM also has a hazard for the same register, EX/MEM takes precedence
        if (! (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs2_addr)) ) begin
            forward_b_sel = 2'b10; // Forward from MEM/WB
        end
    end
end

// Select ALU operands based on forwarding
wire [31:0] memwb_result; // Data to be written in WB stage
assign memwb_result = memwb_memread ? memwb_mem_data : memwb_alu_result;

always @(*) begin
    case (forward_a_sel)
        2'b01: ex_op1 = exmem_alu_result;
        2'b10: ex_op1 = memwb_result;
        default: ex_op1 = idex_rs1_data;
    endcase

    case (forward_b_sel)
        2'b01: ex_op2 = exmem_alu_result;
        2'b10: ex_op2 = memwb_result;
        default: ex_op2 = idex_rs2_data;
    endcase
end

// ALU
always @(*) begin
    case (idex_alu_op)
        `ALU_ADD: ex_alu_result = ex_op1 + (idex_alu_src ? idex_imm : ex_op2);
        `ALU_SUB: ex_alu_result = ex_op1 - (idex_alu_src ? idex_imm : ex_op2);
        `ALU_AND: ex_alu_result = ex_op1 & (idex_alu_src ? idex_imm : ex_op2);
        `ALU_OR:  ex_alu_result = ex_op1 | (idex_alu_src ? idex_imm : ex_op2);
        `ALU_XOR: ex_alu_result = ex_op1 ^ (idex_alu_src ? idex_imm : ex_op2);
        `ALU_SLT: ex_alu_result = ($signed(ex_op1) < $signed(idex_alu_src ? idex_imm : ex_op2)) ? 32'b1 : 32'b0;
        default:  ex_alu_result = 32'b0;
    endcase
end

// Branch/Jump Target Calculation
assign ex_branch_target = idex_pc + idex_imm;
assign ex_jump_target   = (idex_opcode == `OPCODE_JAL) ? (idex_pc + idex_imm) : (ex_op1 + idex_imm); // JALR uses rs1 + imm

// Branch Condition Check
always @(*) begin
    ex_branch_taken = 1'b0;
    if (idex_branch) begin
        case (id_funct3) // Use id_funct3 as it's the original from ID stage
            `FUNCT3_BEQ: ex_branch_taken = (ex_op1 == ex_op2);
            `FUNCT3_BNE: ex_branch_taken = (ex_op1 != ex_op2);
            `FUNCT3_BLT: ex_branch_taken = ($signed(ex_op1) < $signed(ex_op2));
            `FUNCT3_BGE: ex_branch_taken = ($signed(ex_op1) >= $signed(ex_op2));
            default: ex_branch_taken = 1'b0;
        endcase
    end
end

// =================================================================
// EX/MEM Pipeline Register
// =================================================================
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        exmem_pc            <= 32'b0;
        exmem_alu_result    <= 32'b0;
        exmem_mem_wdata     <= 32'b0;
        exmem_rd_addr       <= 5'b0;
        exmem_regwrite      <= 1'b0;
        exmem_memread       <= 1'b0;
        exmem_memwrite      <= 1'b0;
        exmem_branch_taken  <= 1'b0;
        exmem_jump          <= 1'b0;
    end else begin
        exmem_pc            <= idex_pc; // For JAL/JALR link address
        exmem_alu_result    <= ex_alu_result;
        exmem_mem_wdata     <= ex_op2; // rs2_data (forwarded)
        exmem_rd_addr       <= idex_rd_addr;
        exmem_regwrite      <= idex_regwrite;
        exmem_memread       <= idex_memread;
        exmem_memwrite      <= idex_memwrite;
        exmem_branch_taken  <= ex_branch_taken;
        exmem_jump          <= idex_jump;
    end
end

// =================================================================
// MEM Stage: Memory Access
// =================================================================
assign dmem_addr  = exmem_alu_result;
assign dmem_wdata = exmem_mem_wdata;
assign dmem_wen   = exmem_memwrite;
assign dmem_be    = 4'b1111; // Full word access for RV32I subset
assign mem_read_data = dmem_rdata;

// =================================================================
// MEM/WB Pipeline Register
// =================================================================
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        memwb_alu_result <= 32'b0;
        memwb_mem_data   <= 32'b0;
        memwb_rd_addr    <= 5'b0;
        memwb_regwrite   <= 1'b0;
        memwb_memread    <= 1'b0;
    end else begin
        memwb_alu_result <= exmem_alu_result;
        memwb_mem_data   <= mem_read_data;
        memwb_rd_addr    <= exmem_rd_addr;
        memwb_regwrite   <= exmem_regwrite;
        memwb_memread    <= exmem_memread;
    end
end

// =================================================================
// WB Stage: Write Back
// =================================================================
assign wb_waddr = memwb_rd_addr;
assign wb_wen   = memwb_regwrite;

always @(*) begin
    if (memwb_memread) begin
        wb_wdata = memwb_mem_data;
    end else if (exmem_jump && exmem_regwrite) begin // JAL/JALR link address (PC+4)
        wb_wdata = exmem_pc + 4;
    end else begin
        wb_wdata = memwb_alu_result;
    end
end

endmodule